// Boots the EE from the reset vector of a user-supplied ROM0 and reports, with
// a reproducible trace, how far the firmware runs before reaching behavior
// that is not modeled. Built either interpreter-only or, with a translation
// generated by `ps2n-aot <rom0> <out.cpp> --bios`, as a hybrid AOT runner.
#include "ps2native/core.hpp"

#include <filesystem>
#include <iomanip>
#include <iostream>
#include <limits>
#include <optional>
#include <sstream>
#include <stdexcept>
#include <string>

namespace {
std::string hex32(std::uint32_t value) {
    std::ostringstream stream;
    stream << "0x" << std::uppercase << std::hex << std::setw(8) << std::setfill('0') << value;
    return stream.str();
}

const ps2native::AotModule* linked_module() {
#ifdef PS2N_BOOT_WITH_AOT
    return &ps2native::aot_module();
#else
    return nullptr;
#endif
}

template <typename Character>
int boot_main(int argc, Character** argv) {
    if (argc < 2) {
        std::cerr << "Usage: ps2n-boot <your-rom0.bin> [--expect-sha256=HEX] [--max-instructions=N]\n"
                     "                 [--console=MODEL[:MAINBOARD]] [--nvm=FILE] [--expect-nvm-sha256=HEX]\n"
                     "                 [--trace=events|full] [--trace-out=FILE] [--tail=N] [--stop-at=0xADDRESS]\n"
                     "                 [--frame-out=FILE.bmp] (GS VRAM snapshot at stop, when supported)\n"
                     "                 [--assume-video-encoder=0xREG:0xVALUE]... (diagnostic experiments only)\n";
        return 2;
    }
    try {
        ps2native::BiosLoadOptions load;
        ps2native::BootOptions options;
        std::optional<std::filesystem::path> trace_out;
        std::optional<std::filesystem::path> frame_out;
        const ps2native::ConsoleHardware* hardware = nullptr;
        std::optional<std::filesystem::path> nvm_path;
        ps2native::NvmLoadOptions nvm_options;
        ps2native::DiagnosticAssumptions assumptions;
        auto number = [](const std::string& text, const char* label) {
            std::size_t used = 0;
            std::uint64_t value = 0;
            try { value = std::stoull(text, &used, 0); }
            catch (const std::exception&) { throw std::runtime_error(std::string("Invalid ") + label); }
            if (used != text.size() || text.empty() || text[0] == '-') throw std::runtime_error(std::string("Invalid ") + label);
            return value;
        };
        for (int i = 2; i < argc; ++i) {
            const auto flag = ps2native::path_utf8(std::filesystem::path(argv[i]));
            if (flag.starts_with("--expect-sha256=")) {
                load.expected_sha256 = flag.substr(16);
            } else if (flag.starts_with("--console=")) {
                hardware = ps2native::find_console_hardware(flag.substr(10));
                if (hardware == nullptr) {
                    std::string known;
                    for (const auto& profile : ps2native::known_console_hardware())
                        known += std::string(" ") + std::string(profile.model) + ":" + std::string(profile.mainboard);
                    throw std::runtime_error("Unknown or ambiguous console " + flag.substr(10) + "; known:" + known);
                }
            } else if (flag.starts_with("--nvm=")) {
                nvm_path = std::filesystem::path(argv[i]).native().substr(6);
            } else if (flag.starts_with("--expect-nvm-sha256=")) {
                nvm_options.expected_sha256 = flag.substr(20);
            } else if (flag.starts_with("--assume-video-encoder=")) {
                const auto text = flag.substr(23);
                const auto colon = text.find(':');
                if (colon == std::string::npos) throw std::runtime_error("Invalid --assume-video-encoder (0xREG:0xVALUE)");
                const auto index = number(text.substr(0, colon), "--assume-video-encoder register");
                const auto value = number(text.substr(colon + 1), "--assume-video-encoder value");
                if (index > 0xFFu || value > 0xFFu) throw std::runtime_error("Invalid --assume-video-encoder (bytes)");
                assumptions.video_encoder_registers.emplace_back(static_cast<std::uint8_t>(index),
                                                                 static_cast<std::uint8_t>(value));
            } else if (flag.starts_with("--max-instructions=")) {
                options.max_instructions = number(flag.substr(19), "--max-instructions");
            } else if (flag == "--trace=events") {
                options.trace = ps2native::TraceLevel::Events;
            } else if (flag == "--trace=full") {
                options.trace = ps2native::TraceLevel::Full;
            } else if (flag.starts_with("--trace-out=")) {
                trace_out = std::filesystem::path(argv[i]).native().substr(12);
            } else if (flag.starts_with("--frame-out=")) {
                frame_out = std::filesystem::path(argv[i]).native().substr(12);
            } else if (flag.starts_with("--tail=")) {
                options.tail_instructions = static_cast<std::size_t>(number(flag.substr(7), "--tail"));
            } else if (flag.starts_with("--stop-at=")) {
                const auto address = number(flag.substr(10), "--stop-at");
                if (address > std::numeric_limits<std::uint32_t>::max()) throw std::runtime_error("Invalid --stop-at");
                options.stop_at = static_cast<std::uint32_t>(address);
            } else {
                throw std::runtime_error("Unrecognized argument " + flag);
            }
        }
        const auto rom = ps2native::read_file(std::filesystem::path(argv[1]));
        const auto bios = ps2native::load_bios_rom0(rom, load);
        const auto* module = linked_module();
        std::optional<ps2native::NvmImage> nvm;
        if (nvm_path) {
            if (hardware == nullptr) throw std::runtime_error("--nvm needs --console: an NVM is validated against its console");
            nvm = ps2native::load_nvm_image(ps2native::read_file(*nvm_path), *hardware, nvm_options);
        } else if (nvm_options.expected_sha256) {
            throw std::runtime_error("--expect-nvm-sha256 needs --nvm");
        }

        std::ostringstream header;
        header << "# ps2-native EE boot trace v1\n"
               << "# rom0 sha256 " << bios.sha256 << "\n"
               << "# romver " << bios.version.romver << ": version " << bios.version.major << '.'
               << std::setw(2) << std::setfill('0') << bios.version.minor << std::setfill(' ')
               << ", region " << bios.version.region << " (" << bios.version.region_code << "), "
               << bios.version.kind << ", built " << bios.version.date << "\n"
               << "# romdir " << hex32(bios.romdir_offset) << ", " << bios.modules.size() << " files\n";
        if (hardware != nullptr)
            header << "# console " << hardware->model << ':' << hardware->mainboard << ", D_ENABLER "
                   << (hardware->d_enabler ? hex32(*hardware->d_enabler) : std::string("unknown")) << " ("
                   << ps2native::profile_evidence_name(hardware->evidence) << ": " << hardware->source << ")\n";
        else
            header << "# console none selected\n";
        if (nvm) {
            header << "# nvm sha256 " << nvm->sha256 << ", model " << nvm->model_name << ", layout "
                   << ps2native::nvm_layout_info(nvm->layout).name << ", configuration checksums";
            for (unsigned area = 0; area < ps2native::kNvmConfigAreas; ++area) {
                header << ' ' << area << ':';
                for (const bool ok : nvm->config_checksum_ok[area]) header << (ok ? '+' : '-');
            }
            header << "\n";
        } else {
            header << "# nvm none\n";
        }
        if (!assumptions.empty()) {
            header << "# DIAGNOSTIC EXPERIMENT (not a boot of a measured console): assumed video encoder registers";
            for (const auto& [index, value] : assumptions.video_encoder_registers)
                header << ' ' << hex32(index).substr(8) << '=' << hex32(value).substr(8);
            header << "\n";
        }
        header << "# engine " << (module != nullptr ? "hybrid: AOT blocks " + std::to_string(module->block_count) +
                                                          " + interpreter fallback"
                                                    : std::string("interpreter only")) << "\n"
               << "# max-instructions " << options.max_instructions << ", trace "
               << (options.trace == ps2native::TraceLevel::Full ? "full" : "events") << "\n";
        std::cout << header.str();
        for (const auto& file : bios.modules) {
            std::cout << "#   " << std::left << std::setw(10) << file.name << std::right << ' '
                      << hex32(file.offset) << ' ' << std::setw(8) << file.size << " bytes";
            if (file.version) std::cout << " version " << hex32(*file.version).substr(6);
            if (!file.comment.empty()) std::cout << " \"" << file.comment << '"';
            std::cout << '\n';
        }

        ps2native::EEState state;
        ps2native::Memory memory;
        ps2native::prepare_ee_boot(bios, module, state, memory, hardware, nvm ? &*nvm : nullptr,
                                   assumptions.empty() ? nullptr : &assumptions);
        const auto report = ps2native::run_ee_boot(state, memory, module, options);
        std::cout << "# GS VRAM revision " << memory.gs().vram().revision() << '\n';
        std::cout << "# GS pixel writes " << memory.gs().vram().pixel_writes() << '\n';
        for (const auto& packet : report.gif_packets) std::cout << "# GIF " << packet << '\n';
        if (frame_out) {
            std::optional<ps2native::Framebuffer> frame;
            try { frame = memory.gs().scanout(state.retired_instructions); }
            catch (const ps2native::DeviceRefusal& error) { std::cout << "# frame unavailable: " << error.what() << '\n'; }
            if (frame) {
                ps2native::save_framebuffer_bmp(*frame_out, *frame);
                std::cout << "# GS VRAM snapshot " << frame->width << 'x' << frame->height
                          << ", RGBA8 sha256 " << ps2native::sha256_hex(frame->rgba)
                          << ", file " << ps2native::path_utf8(*frame_out) << '\n';
            }
        }

        if (trace_out) {
            std::string text = header.str();
            for (const auto& line : report.trace) { text += line; text += '\n'; }
            (void)ps2native::write_text_if_changed(*trace_out, text);
        } else {
            for (const auto& line : report.trace) std::cout << line << '\n';
        }
        if (!report.sio_output.empty()) {
            // Printable ASCII as is; everything else as \xNN, one line per guest line.
            std::cout << "# EE SIO output (" << report.sio_output.size() << " bytes)\n# | ";
            for (const unsigned char c : report.sio_output) {
                if (c == '\n') std::cout << "\n# | ";
                else if (c >= 0x20u && c < 0x7Fu) std::cout << static_cast<char>(c);
                else if (c != '\r') std::cout << "\\x" << std::hex << std::setw(2) << std::setfill('0')
                                              << static_cast<unsigned>(c) << std::dec;
            }
            std::cout << '\n';
        }
        std::cout << "# IOP: " << report.iop_instructions << " instructions, PC " << hex32(report.iop_pc)
                  << (report.iop_stop ? ", stopped" : ", running") << '\n';
        for (const auto& event : report.iop_events) std::cout << "#   " << event << '\n';
        if (!report.video_encoder_transactions.empty()) {
            std::cout << "# video encoder bus: " << report.video_encoder_transactions.size() << " transactions\n";
            for (const auto& line : report.video_encoder_transactions) std::cout << "#   " << line << '\n';
        }
        std::cout << "# last " << report.tail.size() << " instructions\n";
        for (const auto& line : report.tail) std::cout << line << '\n';
        std::cout << "# result " << ps2native::boot_outcome_name(report.outcome)
                  << "; retired " << report.retired << " (aot " << report.aot_instructions
                  << ", interpreter " << report.interpreted_instructions << ", engine switches "
                  << report.engine_switches << ")\n";
        if (report.outcome == ps2native::BootOutcome::BlockPoint)
            std::cout << "# block point " << hex32(report.pc) << " [" << report.category << "] " << report.reason << '\n';
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "ps2n-boot: " << error.what() << '\n';
        return 1;
    }
}
} // namespace

#ifdef _WIN32
int wmain(int argc, wchar_t** argv) { return boot_main(argc, argv); }
#else
int main(int argc, char** argv) { return boot_main(argc, argv); }
#endif
